<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">REFLECTIONS</span><h2>إدارة الخواطر</h2><p>مساحة منفصلة للخواطر مع الحالات الفعلية الموجودة في قاعدة البيانات.</p></div><form class="admin-v2-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="البحث في الخاطرة أو الكاتب"><select name="status"><option value="">كل الحالات</option><?php foreach(['draft'=>'مسودة','review'=>'مراجعة','changes'=>'تعديلات','rejected'=>'مرفوضة','published'=>'منشورة'] as $key=>$label):?><option value="<?=e($key)?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><button class="admin-v2-button primary" type="submit">تصفية</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>الخاطرة</th><th>الكاتب</th><th>الحالة</th><th>التحديث</th><th>إجراء</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="admin-v2-empty">لا توجد خواطر.</div></td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=e((string)($row['title']??'خاطرة نصية'))?></strong><small><?=e((string)($row['slug']??''))?></small></td><td><?=e((string)$row['author_name'])?></td><td><span class="admin-v2-badge <?=e((string)$row['status'])?>"><?=e((string)$row['status'])?></span></td><td><?=e((string)$row['updated_at'])?></td><td><details class="admin-v2-actions"><summary>تغيير الحالة</summary><form method="post" action="/admin-v2/thoughts/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><select name="status"><option value="draft">مسودة</option><option value="review">مراجعة</option><option value="changes">تعديلات</option><option value="rejected">مرفوضة</option><option value="published">منشورة</option></select><button class="admin-v2-small-button" type="submit">حفظ</button></form></details></td></tr><?php endforeach;endif;?></tbody></table></div></section>
